// goldenrunner_test.go — the Phase-4 closer: the 30-link offline golden
// runner equivalent (the reference's tools/run_golden_websites.py
// --offline — CI's mode — replayed in Go).
//
// testdata/goldenwebsites.golden.json is GENERATED by
// testdiff/goldens/dump_goldenwebsites.py from the unmodified reference
// (assadigit/GitCurator @ 98f4fc7): the generator drives the runner's
// OWN main() (--offline) over its own tests/golden/websites.json corpus
// — the fake LLM answering from the golden file, canned pages feeding
// the fetch — into a THROWAWAY vault, with every clock frozen at
// 2026-10-17 12:00:00 local and both temp roots + the reference app
// dir folded to '<tmp>'/'<app>' by REPLACE (the report EMBEDS the
// taxonomy path; the results embed the vault root; the console embeds
// the report path). The generator runs the payload twice and refuses
// to write unless the two dumps are byte-identical.
//
// This test replays the SAME corpus through this package's port with
// the same seams (the offline fetch + the offline LLM rebuilt as the
// runner's own logic, the same config dict, the same frozen clock) and
// byte-compares: the canned pages, the LLM choreography (url/task/
// reply per call — 90 calls: classify, classify, analyze per link) +
// the first three prompts, the per-link results, the produced notes
// (the whole throwaway vault tree), the report, the console output,
// and the exit-code law (0 iff no invalid taxonomy answer). NO
// network, TEMP VAULTS ONLY.
//
// THE LAW: goldens are never hand-edited; a divergence is either a Go
// bug (fix the port) or a reference behavior change (regenerate + say
// so in the commit).
package websitepipeline

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"
	"unicode"

	"github.com/assadigit/second-brain-project/internal/helpers"
	"github.com/assadigit/second-brain-project/internal/links"
	"github.com/assadigit/second-brain-project/internal/llmclient"
	"github.com/assadigit/second-brain-project/internal/storage"
	"github.com/assadigit/second-brain-project/internal/taxonomy"
	"github.com/assadigit/second-brain-project/internal/webfetch"
)

// --- the golden document --------------------------------------------------

// gwEntry is one corpus entry (tests/golden/websites.json's shape).
type gwEntry struct {
	URL                 string `json:"url"`
	ExpectedCategory    string `json:"expected_category"`
	ExpectedSubcategory string `json:"expected_subcategory"`
	Notes               string `json:"notes"`
}

var (
	gwRaw    map[string]any
	gwCorpus []gwEntry
)

// gwLoad reads the golden once (the raw tree for the byte-comparisons +
// the typed corpus for driving the replay).
func gwLoad(t *testing.T) []gwEntry {
	t.Helper()
	if gwCorpus != nil {
		return gwCorpus
	}
	data, err := os.ReadFile("testdata/goldenwebsites.golden.json")
	if err != nil {
		t.Fatalf("golden file: %v", err)
	}
	if err := json.Unmarshal(data, &gwRaw); err != nil {
		t.Fatalf("golden json: %v", err)
	}
	var doc struct {
		Corpus []gwEntry `json:"corpus"`
	}
	if err := json.Unmarshal(data, &doc); err != nil {
		t.Fatalf("golden corpus: %v", err)
	}
	if len(doc.Corpus) != 30 {
		t.Fatalf("golden corpus has %d entries, want 30", len(doc.Corpus))
	}
	gwCorpus = doc.Corpus
	return gwCorpus
}

// gwStr reads a top-level golden string section.
func gwStr(t *testing.T, key string) string {
	t.Helper()
	v, ok := gwRaw[key].(string)
	if !ok {
		t.Fatalf("golden section %q is not a string", key)
	}
	return v
}

// gwInt reads a top-level golden number section.
func gwInt(t *testing.T, key string) int {
	t.Helper()
	v, ok := gwRaw[key].(float64)
	if !ok {
		t.Fatalf("golden section %q is not a number", key)
	}
	return int(v)
}

// gwTaxPath is the Go repo's byte-identical copy of the reference's
// shipped taxonomy (sha256-pinned equal at T-40 time; the replay's
// config points the pipeline at it exactly the way the runner's default
// resolves the reference's own copy).
func gwTaxPath(t *testing.T) string {
	t.Helper()
	p := filepath.Join("..", "..", "assets", "taxonomy",
		"website-library-categories.md")
	abs, err := filepath.Abs(p)
	if err != nil {
		t.Fatalf("abs taxonomy path: %v", err)
	}
	if _, err := os.Stat(abs); err != nil {
		t.Fatalf("taxonomy file: %v", err)
	}
	return abs
}

// gwFold folds the Go side's per-run facts to the golden's placeholders
// (a REPLACE, not a prefix test — the report EMBEDS the taxonomy path).
func gwFold(s, tmpRoot, assetsDir string) string {
	s = strings.ReplaceAll(s, filepath.ToSlash(tmpRoot), "<tmp>")
	s = strings.ReplaceAll(s, filepath.ToSlash(assetsDir), "<app>")
	return s
}

// --- the Go twins of the runner's offline seams ----------------------------

// gwCapitalize mirrors Python str.capitalize: the first rune
// uppercased, the rest lowercased (the canned page's title quirk —
// "AI illustration maker — …" capitalizes to "Ai illustration maker —
// …"; the corpus's own bytes prove it).
func gwCapitalize(s string) string {
	if s == "" {
		return s
	}
	r := []rune(s)
	return string(unicode.ToUpper(r[0])) + helpers.PyLower(string(r[1:]))
}

// gwOfflineFetch mirrors tools/run_golden_websites.py offline_fetch: a
// canned full page per golden entry keyed by canonical URL. Offline
// mode touches NO network.
func gwOfflineFetch(entries []gwEntry) FetchFn {
	byURL := make(map[string]*gwEntry, len(entries))
	for i := range entries {
		byURL[links.NormalizeWebsiteURL(entries[i].URL)] = &entries[i]
	}
	return func(rawURL string, opts *webfetch.Options) *webfetch.FetchResult {
		var entry *gwEntry
		if e, ok := byURL[links.NormalizeWebsiteURL(rawURL)]; ok {
			entry = e
		}
		notes := ""
		if entry != nil {
			notes = entry.Notes
		}
		titleSrc, desc := notes, notes
		if titleSrc == "" {
			titleSrc = "Golden test site"
		}
		if desc == "" {
			desc = "Offline golden-run fixture page."
		}
		html := "<!doctype html><html><head><title>" + gwCapitalize(titleSrc) +
			"</title><meta name=\"description\" content=\"" + desc +
			"\">" + "</head><body><p>Offline golden-run fixture page for the " +
			"Websites pipeline. This body text stands in for the real " +
			"page so the pipeline runs end to end without any network " +
			"access at all.</p></body></html>"
		status := 200
		return &webfetch.FetchResult{
			URL: rawURL, FinalURL: rawURL, Status: "full", Reason: "",
			HTTPStatus: &status, ContentType: "text/html; charset=utf-8",
			Charset: "utf-8", Body: []byte(html), Text: html,
			ElapsedS: 0.0,
		}
	}
}

// gwLLMRecord is one observed LLM call (the fake's own URL scan + the
// task tag + the exact reply bytes).
type gwLLMRecord struct {
	URL   string
	Task  string
	Reply string
}

// gwPromptSample pins the first three calls' message shapes.
type gwPromptSample struct {
	N       int
	Role    string
	Content string
}

// gwOfflineLLM mirrors tools/run_golden_websites.py offline_llm: keyed
// by canonical URL, answers from the golden file; the URL is recovered
// from the prompt's first 'Website: ' line (the w03 analyze prompt has
// none — its answer is the default analysis, the quirk every golden
// note is named "Golden test site" by). Replies ride storage's
// Python-json.dumps byte law (OrderedMap insertion order +
// PyDumpsCompact). Every call is recorded for the choreography diff.
func gwOfflineLLM(entries []gwEntry) (LLMCallFn, *[]gwLLMRecord, *[]gwPromptSample) {
	byURL := make(map[string]*gwEntry, len(entries))
	for i := range entries {
		byURL[links.NormalizeWebsiteURL(entries[i].URL)] = &entries[i]
	}
	var calls []gwLLMRecord
	var prompts []gwPromptSample
	fn := func(messages []llmclient.Message, task string) string {
		text := ""
		if len(messages) > 0 {
			text = messages[0].Content
		}
		url := ""
		for _, line := range helpers.SplitLines(text) {
			if strings.HasPrefix(line, "Website: ") {
				url = strings.TrimSpace(line[len("Website: "):])
				break
			}
		}
		var entry *gwEntry
		if e, ok := byURL[links.NormalizeWebsiteURL(url)]; ok {
			entry = e
		}
		var reply string
		if strings.Contains(text, "filing a website into a personal library") {
			cat := "Design"
			if entry != nil {
				cat = entry.ExpectedCategory
			}
			m := storage.NewOrderedMap()
			m.Set("category", cat)
			m.Set("confidence", "high")
			m.Set("reason", "golden offline mode")
			reply = storage.PyDumpsCompact(m)
		} else if strings.Contains(text, "was filed under") {
			sub := "none"
			if entry != nil && entry.ExpectedSubcategory != "" {
				sub = entry.ExpectedSubcategory
			}
			m := storage.NewOrderedMap()
			m.Set("subcategory", sub)
			m.Set("confidence", "high")
			reply = storage.PyDumpsCompact(m)
		} else {
			name := "Golden test site"
			if entry != nil && entry.Notes != "" {
				name = entry.Notes
			}
			m := storage.NewOrderedMap()
			m.Set("name", name)
			m.Set("one_line", "Offline golden-run placeholder description.")
			m.Set("core_offerings", []any{"Offline validation",
				"Report generation", "No network"})
			m.Set("standout_feature", "")
			m.Set("best_used_for",
				"Use when you need to validate the pipeline without network.")
			m.Set("pricing", "unknown")
			m.Set("login_required", "unknown")
			m.Set("similar_tools", []any{})
			m.Set("tags", []any{"golden"})
			m.Set("confidence", "high")
			reply = storage.PyDumpsCompact(m)
		}
		calls = append(calls, gwLLMRecord{URL: url, Task: task, Reply: reply})
		if len(prompts) < 3 {
			s := gwPromptSample{N: len(messages)}
			if len(messages) > 0 {
				s.Role = messages[0].Role
				s.Content = messages[0].Content
			}
			prompts = append(prompts, s)
		}
		return reply
	}
	return fn, &calls, &prompts
}

// --- the Go twins of the runner's report renderer --------------------------

// gwOfflineNotes is the runner's own offline-mode notes string (the
// report's Notes section — byte-pinned by the golden).
const gwOfflineNotes = "Offline mode: the \"actual\" answers COME FROM the " +
	"golden file via a fake LLM — this validates the machinery " +
	"(prompts, validation, note building), not the model. " +
	"Run --live for the real comparison."

// gwVerdictOf mirrors the runner's verdict_of.
func gwVerdictOf(r *Result, expCat, expSub string, tax *taxonomy.Taxonomy) string {
	if r.Outcome != "processed" {
		e := r.Error
		if e == "" {
			e = r.Outcome
		}
		if e == "" {
			e = "?"
		}
		return "⚠️ " + e
	}
	actualCat := r.Category
	if !tax.IsCategory(actualCat) {
		return "❌ INVALID CATEGORY: " + actualCat
	}
	if actualCat != expCat {
		return "❌ expected " + expCat
	}
	es, as := expSub, r.Subcategory
	if es == as {
		return "✅ exact"
	}
	if es == "" || as == "" {
		if es == "" {
			es = "(none)"
		}
		return "◐ subcategory: expected " + es
	}
	return "◐ subcategory: expected " + es
}

// gwRenderReport mirrors the runner's render_report (the tool's own
// renderer, ported byte-exactly; gen is the frozen clock).
func gwRenderReport(mode string, entries []gwEntry, results []Result,
	tax *taxonomy.Taxonomy, notes string, gen time.Time) string {
	var b strings.Builder
	b.WriteString("# Golden-set report — Websites pipeline (" + mode + " mode)\n")
	b.WriteString("\n")
	b.WriteString("*Generated: " + gen.Format("2006-01-02 15:04") +
		fmt.Sprintf(" · %d links · taxonomy: %s*\n", len(entries), tax.Summary()))
	b.WriteString("\n")
	b.WriteString("> A golden run writes to a throwaway vault and a throwaway cache — never to the real ones.\n")
	b.WriteString("\n")
	counts := map[string]int{"exact": 0, "category_only": 0, "mismatch": 0, "review": 0}
	n := len(entries)
	if len(results) < n {
		n = len(results)
	}
	for i := 0; i < n; i++ {
		v := gwVerdictOf(&results[i], entries[i].ExpectedCategory,
			entries[i].ExpectedSubcategory, tax)
		switch {
		case strings.HasPrefix(v, "✅"):
			counts["exact"]++
		case strings.HasPrefix(v, "◐"):
			counts["category_only"]++
		case strings.HasPrefix(v, "⚠️"):
			counts["review"]++
		default:
			counts["mismatch"]++
		}
	}
	b.WriteString("## Summary\n\n")
	b.WriteString("| Verdict | Count |\n")
	b.WriteString("|---------|-------|\n")
	fmt.Fprintf(&b, "| ✅ exact (category + subcategory) | %d |\n", counts["exact"])
	fmt.Fprintf(&b, "| ◐ category match, subcategory differs | %d |\n", counts["category_only"])
	fmt.Fprintf(&b, "| ❌ category mismatch | %d |\n", counts["mismatch"])
	fmt.Fprintf(&b, "| ⚠️ needs review / failed | %d |\n\n", counts["review"])
	invalid := 0
	for i := range results {
		if results[i].Outcome == "processed" &&
			!tax.IsCategory(results[i].Category) {
			invalid++
		}
	}
	fmt.Fprintf(&b, "**Model answers that were invalid taxonomy names: "+
		"%d** (the pipeline validates every answer and falls back to "+
		"_review, so this must be 0.)\n\n", invalid)
	b.WriteString("## Side by side\n\n")
	b.WriteString("| # | Link | Fetched | Expected | Actual | Verdict |\n")
	b.WriteString("|---|------|---------|----------|--------|---------|\n")
	for i := 0; i < n; i++ {
		e, r := entries[i], results[i]
		exp := e.ExpectedCategory
		if exp == "" {
			exp = "—"
		}
		if e.ExpectedSubcategory != "" {
			exp += " / " + e.ExpectedSubcategory
		}
		act := r.Category
		if act == "" {
			act = "—"
		}
		if r.Subcategory != "" {
			act += " / " + r.Subcategory
		}
		v := gwVerdictOf(&r, e.ExpectedCategory, e.ExpectedSubcategory, tax)
		fmt.Fprintf(&b, "| %d | [%s](%s) | %s | %s | %s | %s |\n",
			i+1, e.URL, e.URL, r.FetchStatus, exp, act, v)
	}
	b.WriteString("\n")
	if notes != "" {
		b.WriteString("## Notes\n\n")
		b.WriteString(notes)
		b.WriteString("\n")
		b.WriteString("\n")
	}
	return b.String()
}

// --- 1. the canned pages ----------------------------------------------------

func TestGoldenWebsitesCannedFetch(t *testing.T) {
	entries := gwLoad(t)
	fetch := gwOfflineFetch(entries)
	got := make([]any, 0, 3)
	for _, idx := range []int{0, 2, 7} {
		fr := fetch(entries[idx].URL, nil)
		if fr.HTTPStatus == nil {
			t.Fatalf("canned fetch %d: nil http status", idx)
		}
		got = append(got, map[string]any{
			"url": fr.URL, "final_url": fr.FinalURL, "status": fr.Status,
			"reason": fr.Reason, "http_status": *fr.HTTPStatus,
			"content_type": fr.ContentType, "charset": fr.Charset,
			"text": fr.Text, "elapsed_s": fr.ElapsedS,
		})
	}
	cmpGoldenJSON(t, "canned_fetch", got, gwRaw["canned_fetch"])
}

// --- 2. THE OFFLINE RUNNER REPLAY ------------------------------------------

func TestGoldenWebsitesOfflineRunner(t *testing.T) {
	entries := gwLoad(t)
	root := t.TempDir()       // the throwaway root (vault + cache.db)
	reportRoot := t.TempDir() // the report's own throwaway root
	vault := filepath.Join(root, "websites")
	dbPath := filepath.Join(root, "cache.db")
	reportPath := filepath.Join(reportRoot, "report.md")
	taxPath := gwTaxPath(t)
	assetsDir, err := filepath.Abs(filepath.Join("..", "..", "assets"))
	if err != nil {
		t.Fatalf("assets dir: %v", err)
	}

	llmFn, calls, prompts := gwOfflineLLM(entries)
	fetch := gwOfflineFetch(entries)
	type logLine struct{ level, msg string }
	var logs []logLine
	logFn := func(msg, level string) { logs = append(logs, logLine{level, msg}) }

	cfg := map[string]any{
		"website_vault_path":  vault,
		"web_fetch_timeout_s": 20,
		"web_domain_delay_s":  1.0,
		"web_blocked_domains": []any{},
		"taxonomy_path":       taxPath,
	}

	var results []Result
	withFrozenClock(t, func() {
		state, err := NewWebsiteStateDB(dbPath)
		if err != nil {
			t.Fatalf("state db: %v", err)
		}
		p, err := NewPipeline(cfg, llmFn,
			func(u string) any { return false },
			state, logFn, nil, nil, nil, fetch, nil, nil)
		if err != nil {
			state.Close()
			t.Fatalf("pipeline: %v", err)
		}
		urls := make([]string, len(entries))
		for i := range entries {
			urls[i] = entries[i].URL
		}
		results = p.Run(urls, nil, nil)
		state.Close()
	})

	tax, err := taxonomy.LoadTaxonomy(taxPath)
	if err != nil {
		t.Fatalf("taxonomy: %v", err)
	}

	// -- the exit-code law (0 iff no invalid taxonomy answer) ---------
	invalid := 0
	processed := 0
	for _, r := range results {
		if r.Outcome == "processed" {
			processed++
			if !tax.IsCategory(r.Category) {
				invalid++
			}
		}
	}
	exitCode := 0
	if invalid != 0 {
		exitCode = 1
	}

	t.Run("results", func(t *testing.T) {
		got := make([]any, len(results))
		for i, r := range results {
			got[i] = map[string]any{
				"url": r.URL, "canonical": r.Canonical,
				"outcome":   r.Outcome,
				"note_path": gwFold(r.NotePath, root, assetsDir),
				"category":  r.Category, "subcategory": r.Subcategory,
				"fetch_status": r.FetchStatus, "error": r.Error,
			}
		}
		cmpGoldenJSON(t, "results", got, gwRaw["results"])
	})

	t.Run("notes", func(t *testing.T) {
		got := map[string]string{}
		err := filepath.WalkDir(vault, func(p string, d os.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() {
				return nil
			}
			rel, err := filepath.Rel(root, p)
			if err != nil {
				return err
			}
			data, err := os.ReadFile(p)
			if err != nil {
				return err
			}
			got[filepath.ToSlash(rel)] = string(data)
			return nil
		})
		if err != nil {
			t.Fatalf("walk vault: %v", err)
		}
		cmpGoldenJSON(t, "notes", got, gwRaw["notes"])
	})

	t.Run("report", func(t *testing.T) {
		got := gwRenderReport("offline", entries, results, tax,
			gwOfflineNotes, frozenClock)
		got = gwFold(got, reportRoot, assetsDir)
		if got != gwStr(t, "report") {
			t.Fatalf("report diverges from the reference golden:\n"+
				"--- go ---\n%s\n--- reference ---\n%s", got, gwStr(t, "report"))
		}
	})

	t.Run("console", func(t *testing.T) {
		var b strings.Builder
		for _, l := range logs {
			b.WriteString("  [" + l.level + "] " + l.msg + "\n")
		}
		fmt.Fprintf(&b, "\nReport: %s\n", reportPath)
		fmt.Fprintf(&b, "Invalid category names: %d (must be 0)\n", invalid)
		fmt.Fprintf(&b, "Processed: %d/%d\n", processed, len(entries))
		got := gwFold(b.String(), reportRoot, assetsDir)
		if got != gwStr(t, "console") {
			t.Fatalf("console diverges from the reference golden:\n"+
				"--- go ---\n%s\n--- reference ---\n%s", got, gwStr(t, "console"))
		}
	})

	t.Run("exit_code", func(t *testing.T) {
		if exitCode != gwInt(t, "exit_code") {
			t.Errorf("exit code = %d, want %d", exitCode, gwInt(t, "exit_code"))
		}
		if invalid != gwInt(t, "invalid") {
			t.Errorf("invalid = %d, want %d", invalid, gwInt(t, "invalid"))
		}
		if processed != gwInt(t, "processed_count") {
			t.Errorf("processed = %d, want %d", processed, gwInt(t, "processed_count"))
		}
	})

	t.Run("llm_choreography", func(t *testing.T) {
		got := make([]any, len(*calls))
		for i, c := range *calls {
			got[i] = map[string]any{
				"url": c.URL, "task": c.Task, "reply": c.Reply,
			}
		}
		cmpGoldenJSON(t, "llm_calls", got, gwRaw["llm_calls"])
	})

	t.Run("prompt_samples", func(t *testing.T) {
		got := make([]any, len(*prompts))
		for i, p := range *prompts {
			got[i] = map[string]any{
				"n_messages": p.N, "role": p.Role, "content": p.Content,
			}
		}
		cmpGoldenJSON(t, "prompt_samples", got, gwRaw["prompt_samples"])
	})
}
